package com.shahboun.aqim;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;
public class DhikrSettingsActivity extends Activity{int G=Color.rgb(15,76,58),I=Color.rgb(248,244,235),T=Color.rgb(35,48,43);android.graphics.Typeface c;int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}GradientDrawable bg(int x){GradientDrawable g=new GradientDrawable();g.setColor(x);g.setCornerRadius(dp(22));return g;}Button b(String s){Button x=new Button(this);x.setText(s);x.setAllCaps(false);x.setGravity(Gravity.CENTER);x.setBackground(bg(Color.WHITE));x.setElevation(dp(4));if(c!=null)x.setTypeface(c,1);return x;}public void onCreate(Bundle z){super.onCreate(z);try{if(Build.VERSION.SDK_INT>=26)c=getResources().getFont(getResources().getIdentifier("cairo","font",getPackageName()));}catch(Exception e){}show();}void show(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(18),dp(20),dp(18),dp(30));r.setBackgroundColor(I);TextView h=new TextView(this);h.setText("تذكير الذكر");h.setTextSize(28);h.setTextColor(G);h.setGravity(Gravity.CENTER);if(c!=null)h.setTypeface(c,1);r.addView(h,new LinearLayout.LayoutParams(-1,dp(70)));SharedPreferences p=getSharedPreferences("aqim",0);Switch on=new Switch(this);on.setText("تشغيل تذكيرات الذكر على شاشة القفل");on.setChecked(p.getBoolean("dhikrReminder",true));if(c!=null)on.setTypeface(c);r.addView(on);int[] mins={10,15,30,60};for(int m:mins){Button x=b("كل "+m+" دقيقة"+(p.getInt("dhikrInterval",10)==m?"  ✓":""));x.setOnClickListener(v->{p.edit().putInt("dhikrInterval",m).putBoolean("dhikrReminder",true).apply();DhikrReminderReceiver.scheduleNext(this);show();});LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,dp(62));q.setMargins(0,dp(9),0,0);r.addView(x,q);}on.setOnCheckedChangeListener((v,onv)->{p.edit().putBoolean("dhikrReminder",onv).apply();if(onv)DhikrReminderReceiver.scheduleNext(this);});TextView n=new TextView(this);n.setText("ساعات هدوء افتراضية: من 23:00 إلى 06:00 حتى لا تزعجك التنبيهات أثناء النوم.");n.setTextColor(T);n.setGravity(Gravity.CENTER);n.setPadding(dp(10),dp(18),dp(10),dp(10));if(c!=null)n.setTypeface(c);r.addView(n);ScrollView s=new ScrollView(this);s.addView(r);setContentView(s);}}
